def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    urgent_prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0

    for opp in alive_opponents:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_opponents += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_aggressive += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                prev_supply = prev.get('supply')
                if prev_supply is not None and float(prev_supply) <= 18.0:
                    urgent_prev_bids.append(float(bid))
                elif opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    tight_supply = supply <= 17.0
    medium_tight = supply <= 19.0
    danger = hp <= 3 or no_water_days >= 1
    severe_danger = hp <= 2 or no_water_days >= 2

    if severe_danger:
        target = max(DAILY_SALARY * 1.15, urgent_high + 3.0)
    elif danger:
        if tight_supply:
            target = max(DAILY_SALARY * 0.95, urgent_high + 2.0)
        else:
            target = max(DAILY_SALARY * 0.82, highest_prev * 0.92)
    else:
        if tight_supply:
            target = max(DAILY_SALARY * 0.62, min(DAILY_SALARY * 0.95, urgent_high * 0.72))
        elif medium_tight:
            target = max(DAILY_SALARY * 0.42, min(DAILY_SALARY * 0.72, highest_prev * 0.52))
        else:
            target = DAILY_SALARY * 0.24

    if rich_aggressive >= 2 and not danger:
        target *= 0.88
    if weak_opponents >= 2 and not severe_danger:
        target *= 0.93
    if day >= 8 and hp >= 5 and no_water_days == 0 and not tight_supply:
        target *= 0.85

    reserve_floor = DAILY_SALARY * max(0, 10 - day)
    max_affordable = budget
    if not severe_danger:
        max_affordable = max(0.0, budget - reserve_floor * 0.15)
        max_affordable = min(budget, max_affordable + DAILY_SALARY * 0.35)

    bid = min(target, max_affordable)

    if danger and bid < DAILY_SALARY * 0.55:
        bid = min(budget, DAILY_SALARY * 0.55)
    if severe_danger and bid < DAILY_SALARY * 0.9:
        bid = min(budget, DAILY_SALARY * 0.9)

    if not danger and not tight_supply and highest_prev >= DAILY_SALARY * 1.8:
        bid = min(bid, DAILY_SALARY * 0.22)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for agent_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((agent_id, o))

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids of alive opponents (immediate reaction)
    yesterday_bids = []
    yesterday_hp_after = []
    for agent_id, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                yesterday_hp_after.append(float(prev['hp_after']))
            except Exception:
                pass

    base_bid = DAILY_SALARY * 0.55

    # If others were bidding aggressively yesterday, we slightly overbid to win water.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))

        # Pressure estimate: low hp_after opponents likely will keep bidding to avoid death.
        low_hp_pressure = 0
        if yesterday_hp_after:
            low_hp_pressure = sum(1 for hp in yesterday_hp_after if hp <= 4) / float(len(yesterday_hp_after))

        # Aggression threshold tuned to meta medium; keep moderate overbid.
        # If highest prev bid is very high, bid closer to it but not fully.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3 and my_no_water_days <= 1:
                target = max(base_bid, avg_prev_bid * 0.85, highest_prev_bid * 0.65)
            else:
                target = max(base_bid, avg_prev_bid * 0.95, highest_prev_bid * 0.75)
        else:
            # Otherwise, bid around avg with a small lift for low-hp pressure.
            target = max(base_bid, avg_prev_bid * (0.9 + 0.15 * low_hp_pressure))

        # Supply scaling: when supply is tighter, competition increases; bid slightly higher.
        # supply in [15,25]; map to factor ~[0.95,1.10]
        supply_factor = 0.95 + (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY) * 0.15
        target *= supply_factor

    else:
        # Fallback if no trace bids available.
        target = base_bid
        if my_hp <= 2 or my_no_water_days >= 2:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * 0.55

    # Ensure we don't overspend: keep some buffer for future days.
    # If my budget is low, prioritize survival.
    if my_budget <= DAILY_SALARY * 1.0:
        cap = my_budget
    elif my_budget <= DAILY_SALARY * 2.0:
        cap = my_budget * 0.85
    else:
        cap = my_budget * 0.7

    # If I'm in danger, bid higher.
    if my_hp <= 2 or my_no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.75)

    # Never bid negative or above cap.
    bid = float(target)
    if bid < 0:
        bid = 0.0
    if bid > cap:
        bid = cap

    # Also avoid bidding above a reasonable fraction of max supply*? (safety)
    # Use WATER_REQ to avoid extreme overbids.
    max_reasonable = DAILY_SALARY * 1.2
    if bid > max_reasonable:
        bid = max_reasonable

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Base bid strategy
    bid = DAILY_SALARY * 0.9 

    # HP-based aggression
    if my_status['hp'] <= 2: 
        bid = DAILY_SALARY * 1.4
    elif my_status['hp'] <= 4: 
        bid = DAILY_SALARY * 1.1
    elif my_status['hp'] >= 8: 
        bid = DAILY_SALARY * 0.8

    # Opponent reaction based on previous day's bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid > DAILY_SALARY * 1.1:
            if my_status['hp'] <= 3:
                bid = max(bid, highest_prev_bid + 5)
            else:
                bid = max(bid, highest_prev_bid * 1.02)
        elif highest_prev_bid > DAILY_SALARY * 0.8:
            bid = max(bid, highest_prev_bid + 1)
        else:
            if my_status['hp'] <= 2:
                bid = max(bid, DAILY_SALARY * 1.2)
            else:
                bid = min(bid, DAILY_SALARY * 0.7)

    # Endgame aggression
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            bid = max(bid, DAILY_SALARY * 1.6)
        else:
            bid = max(bid, DAILY_SALARY * 1.1)
    elif remaining_days == 1:
        if my_status['hp'] <= 7:
            bid = max(bid, DAILY_SALARY * 1.8)
        else:
            bid = max(bid, DAILY_SALARY * 1.2)

    # Ensure bid is not negative and within budget
    final_bid = min(my_status['budget'], bid)
    final_bid = max(0.0, final_bid)

    return final_bid

